def num(k,l,mn,mx,v,step=1,u=''):return dict(key=k,label=l,min=mn,max=mx,value=v,step=step,unit=u)
def opt(k,l,values,v=None):return dict(key=k,label=l,value=v or values[0][0],options=[dict(value=a,label=b) for a,b in values])
def sp(s):return s.split('|') if isinstance(s,str) else s
SRC={'7上':'bio-pep7up-text','7下':'bio-pep7down-text','8上':'bio-pep8up-text','8下':'bio-pep8down-guide'}
NOTES={
 'microscope':'显微图为原创结构示意，不是显微照片。放大倍数为目镜×物镜；焦距滑块仅示意调焦，不是实际镜筒位移。视野大小采用同一目镜的比例关系。',
 'anatomy':'结构与位置为教学示意，比例及颜色经过简化；切换结构只改变观察重点，不代表对真实生物进行切割。',
 'survey':'场景中的数量为可编辑的教学样本；统计结论只适用于该样本，不能冒充校园、地区或人群的实测结果。',
 'germination':'采用条件逻辑说明种子萌发，不给出适用于所有种类的温度阈值或真实生长速度；动画时间不是萌发所需天数。',
 'plant':'表示植物运输、生长和气孔开闭的机制，不预测真实株高、蒸腾量或个体产量。',
 'photosynthesis':'采用有无必要条件的定性模型；光合和呼吸同时存在，实际反应强度受多因素影响。颜色是处理后的检验结果示意。',
 'respiration':'活种子与对照的定性现象示意，不能从动画强弱读出实测氧耗量或热量。',
 'microbe':'只在屏幕中模拟密闭培养或食品发酵的条件与现象。菌落图案不是实测菌落数，也不能用于鉴定病原体或判定食品安全。',
 'digestion':'用淀粉是否残留解释碘液显色。模型只比较适宜、低温和高温处理，不把消化程度写成实测浓度。',
 'calorimetry':'使用用户输入的水质量、温升与燃烧质量计算水吸收的热量；不假定热效率100%，结果不等同食品标签总能量。',
 'lung':'气球和橡皮膜模拟肺及膈，不能代表胸廓全部结构和生理压力。膜位移仅用于展示通气方向。',
 'circulation':'血液及血管比例为示意，红蓝表示含氧相对高低，并非人体内血液呈蓝色。流动方向遵循心脏与循环路径。',
 'kidney':'过滤、重吸收用成分去向表示，未建模实际肾小球滤过率；结果不能用于判断个人肾功能。',
 'reaction':'反应时间由尺下落的距离按自由落体公式换算，包含感知、神经传导及动作时间，不能直接等同神经传导速度。',
 'reflex':'反射弧信号传播为示意，动画速度不代表真实潜伏期，不能用本页进行神经功能诊断。',
 'muscle':'简化骨—关节—肌肉结构模型，强调拮抗肌协调；肌长和关节角度不是人体生物力学测量结果。',
 'ecology':'情景或比率模型用于比较生物与环境关系，不预测真实种群数量。生态瓶不存在保证永久稳定的配方。',
 'genetics':'按单基因、完全显性、配子等概率且随机结合的假设计算理论概率；比例不是每一小批后代的必然实测结果。',
 'variation':'数据为可编辑的合成教学样本，展示抽样、平均数与分布；不能只由外观差异确定遗传或环境原因。',
 'selection':'模型中的不同存活概率是人为设定的捕食情景，用于说明自然选择，不代表自然种群的实际选择系数。',
 'reproduction':'表示生殖发育的阶段与必要条件，不预测发育天数或成活率；动物饲养需要满足物种的真实环境要求。',
 'health':'提供教材级结构、统计或防护原理练习；输入数字为样例或用户记录，不作诊断、处方或急救技能认证。'
}
def add(id,term,chapter,title,kind,model,controls,objective,apparatus,steps,observations,conclusion,exam,pitfalls,qa,example,answer,ncet=(),evidence=None,safety=None,config=None):
 rec=dict(id='bio-'+id,subject='biology',term=term,chapter=chapter,title=title,kind=kind,tags=['教材实践' if evidence is not False else '课标拓展']+(['基本目录'] if ncet else []),sourceIds=[SRC[term]] if evidence is not False else ['bio-ncet2023'],objective=objective,apparatus=sp(apparatus),steps=sp(steps),observations=sp(observations),conclusion=conclusion,examPoints=sp(exam),pitfalls=sp(pitfalls),questions=[dict(q=qa[0],a=qa[1])],safety=sp(safety or '实物操作遵守教师指导；不接触未知生物，不将实验材料放入口中。'),model=model,modelNote=NOTES[model],controls=controls,workedExample=dict(title='规范例题' if any(x in answer for x in ['%','×','÷','=','倍','s','J']) else '规范作答',given=example[0],steps=[dict(title=t,text=x) for t,x in zip(['明确条件','观察或依据','推理与表达'],example[1:])],answer=answer),ncetIds=list(ncet),evidenceTitles=sp(evidence or title) if evidence is not False else [],evidenceStatus='现行教材公开文本核对' if term!='8下' and evidence is not False else '现行教师用书公开目录及活动说明核对' if evidence is not False else '2023基本目录已核对；本网站学期归类')
 if ncet and 'bio-ncet2023' not in rec['sourceIds']:rec['sourceIds'].append('bio-ncet2023')
 if config:rec['config']=config
 R.append(rec)
