add('paramecium','7上','第一单元 第三章 从细胞到生物体','观察草履虫并探究其趋性','学生实验','microscope',[opt('stimulus','右侧刺激',[('food','适宜食物'),('salt','食盐刺激'),('none','无刺激对照')]),num('zoom','示意放大',1,3,1,.5)],'观察单细胞生物并比较其对不同刺激的反应。','草履虫教学培养液|载玻片与滴管|少量棉纤维|显微镜','从培养液表层取样并低倍观察。|用少量棉纤维减慢运动。|设置连通液滴及对照，改变一种刺激，记录分布。','草履虫由一个细胞完成取食、运动、排泄等活动。|有害刺激与适宜刺激可引起不同方向的运动。','草履虫能对环境刺激作出反应，不能据此认为它有神经系统。','取样表层含氧较多|单一变量与对照','不能将趋性称为反射|不要用一只个体的一次运动下结论',('草履虫遇盐离开属于反射吗？','不属于；反射需要神经系统参与，草履虫没有神经系统。'),('盐粒放于右侧后草履虫多数向左运动，对照无此差异。','变量为盐刺激，其他条件相同。','比较实验与对照的运动方向。','结果支持草履虫对该刺激有趋避反应。'),'该现象支持草履虫能对刺激作出反应，不属于反射。',(2,7),config={'specimen':'paramecium'},safety='培养液不可入口；用后按教师要求处置，不倒入饮水容器。')
add('cell-model','7上','第一单元 第三章 从细胞到生物体','制作细胞模型','拓展探究','anatomy',[opt('type','模型类型',[('plant','植物细胞'),('animal','动物细胞')]),opt('view','标注内容',[('whole','整体结构'),('detail','遗传信息所在结构')])],'用可解释的模型表现细胞基本结构及动植物细胞差异。','可重复使用的模型材料|结构标签|设计草图','选择一种细胞作为原型。|用不同形状代表膜、质、核等结构。|解释材料与真实结构的对应关系并修改模型。','模型有助于表示结构位置，但放大比例、颜色与质感不同于真实细胞。|植物细胞模型应表现细胞壁。','模型必须兼顾结构准确性与表达清楚，并明确其局限。','模型不是实物|遗传信息主要在细胞核','不能给动物细胞添细胞壁|不能让所有细胞模型都有叶绿体',('为什么要标注模型局限？','避免把示意颜色、形状或比例误认为真实细胞的固定属性。'),('制作洋葱内表皮细胞模型，是否应加叶绿体？','明确选择的细胞是鳞片叶内表皮。','这种细胞通常不含叶绿体。','保留细胞壁、膜、质、核和大液泡等应有结构。'),'不应仅因其为植物细胞就加入叶绿体。',(4,))
add('plants','7上','第二单元 第一章 藻类与植物的类群','观察不同类群的植物','小实验','anatomy',[opt('organism','类群',[('alga','藻类'),('moss','苔藓植物'),('fern','蕨类植物'),('pine','裸子植物'),('flowering','被子植物')])],'比较身体分化、输导结构和繁殖特征。','藻类及植物标本或照片|放大镜|比较表','观察有无根、茎、叶分化。|比较孢子和种子等繁殖结构。|区分裸子与被子植物种子外有无果皮包被。','苔藓植物有类似茎叶的结构，假根主要起固定作用。|蕨类有根茎叶及输导组织；种子植物用种子繁殖。','植物分类依据一组形态和繁殖特征，不能只按大小或栖息地。','孢子与种子区别|果实与裸露种子区别','藻类不都属于植物界的现行分类范围|松的球果不是被子植物的果实',('蕨类有输导组织，为什么仍不是种子植物？','它通常以孢子繁殖，不产生种子。'),('某植物有根、茎、叶，叶背有孢子囊群，无种子。','提取根茎叶和孢子两项证据。','蕨类通常具输导组织并以孢子繁殖。','不能因植株较高就判为种子植物。'),'该标本符合蕨类植物的主要特征。',(8,),evidence='几种苔藓植物和蕨类植物|种子的着生位置')
add('seed-structure','7上','第二单元 第一章 藻类与植物的类群','观察种子的结构','学生实验','anatomy',[opt('seed','种子',[('bean','菜豆'),('maize','玉米')]),opt('view','观察层次',[('whole','整体剖面'),('detail','胚和贮藏结构')])],'识别胚各部分，并比较菜豆与玉米的营养储存部位。','浸软菜豆与玉米|放大镜|镊子|教学剖切标本和碘液','观察外形并辨认种皮。|按教师要求观察纵切面或剥开的子叶。|识别胚根、胚轴、胚芽、子叶及胚乳。','菜豆有两片较肥厚子叶。|玉米胚一侧较小，胚乳通常遇碘液变蓝。','胚是新植物的幼体；不同种子储存营养的主要部位不同。','菜豆子叶储存营养|玉米胚乳储存营养','不能把整粒玉米都叫胚|玉米粒严格说是颖果',('玉米滴碘后胚乳变蓝说明什么？','说明该区域含有淀粉，不能说明只有该区域含全部营养。'),('菜豆与玉米萌发初期主要营养来源分别是什么？','比较两者贮藏结构。','菜豆种子子叶肥厚；玉米有较发达胚乳。','将结构与营养供给功能相联系。'),'主要分别来自菜豆子叶和玉米胚乳。',(17,),safety='剖切仅由教师指导，刀口避开手指；碘液不可入口。')
add('animal-groups','7上','第二单元 第二章 动物的类群','观察不同类群动物的形态结构','小实验','anatomy',[opt('animal','观察对象',[('earthworm','蚯蚓'),('clam','缢蛏'),('locust','蝗虫'),('fish','鲫鱼'),('frog','青蛙'),('rabbit','家兔')])],'以呼吸、身体分部和附肢等证据区分动物类群。','动物教学标本或影像|放大镜|比较记录表','从外部形态开始记录。|观察与运动、呼吸有关的结构。|依据多项特征判断类群并说明与环境的联系。','鱼通常用鳃呼吸，鳍参与运动和平衡。|蚯蚓体表湿润、身体分节；昆虫有外骨骼和三对足。','类群判断应采用关键结构证据，不能只依生活环境。','鱼鳃和鳍功能不同|青蛙成体肺呼吸并由皮肤辅助','鲸不是鱼|不能堵鳃、绑鳍或使动物失水验证功能',('为什么不能按是否在水中生活区分鱼类？','水中还生活着哺乳动物及其他类群，应根据结构和生殖等特征判断。'),('观察到一个动物身体分头胸腹，有三对足，判断类群。','采用身体分部和足数两项证据。','昆虫通常具有头胸腹与三对足。','结论仅据这些形态特征，不据体型大小。'),'其主要形态符合昆虫特征。',(9,),evidence='鱼的形态、结构和运动|蛙的形态',safety='使用合法教学标本或影像；不捕捉受保护动物，不进行伤害动物的验证。')
add('bird','7上','第二单元 第二章 动物的类群','鸟适于飞行的形态结构特点','学生实验','anatomy',[opt('feature','观察重点',[('shape','体形与翼'),('feather','羽毛'),('bone','骨与胸肌'),('air','呼吸结构')])],'结合观察说明鸟类结构与飞行相适应。','羽毛标本|鸟骨骼模型|鸟类影像','观察流线型体形和前肢形成翼。|比较羽毛结构、胸骨和胸肌。|用模型了解气囊与肺的配合。','部分长骨内部中空，胸肌发达。|气囊辅助呼吸，气体交换发生在肺。','减轻质量、提供动力与高效供氧等特征共同支持飞行。','气囊不进行气体交换|结构功能联系需完整表达','不能认为鸟骨全为空心|不是所有鸟都能飞',('只写“身体轻”能完整解释鸟飞行吗？','不能，还应联系翼、胸肌、骨骼支持以及呼吸等方面。'),('请用结构—功能句式解释鸟的胸肌发达。','结构为胸肌发达并附着于胸骨等部位。','肌肉收缩牵引翼运动。','将结构与提供飞行动力联系。'),'发达胸肌通过收缩驱动翼运动，为飞行提供动力。',(9,))
add('teeth','7上','第二单元 第二章 动物的类群','比较兔和狼的牙齿','小实验','anatomy',[opt('animal','头骨',[('rabbit','兔'),('wolf','狼')])],'比较门齿、犬齿和臼齿，解释食性适应。','头骨模型或图片|牙齿结构标签','定位门齿、犬齿、臼齿。|比较牙齿形态及发达程度。|联系切断、撕裂和磨碎食物的功能。','兔门齿及臼齿较适于切断磨碎植物，通常无犬齿。|狼犬齿发达，利于撕裂。','牙齿分化提高食物处理能力，并与食性相适应。','用证据联系结构与食性','不能只凭牙齿就断定全部食谱',('兔为何需要发达臼齿？','臼齿有利于磨碎植物性食物。'),('比较兔与狼，用犬齿解释二者取食差异。','先确定有无发达犬齿。','犬齿适于刺入和撕裂食物。','将狼的发达犬齿与食肉特点联系。'),'狼发达的犬齿利于撕裂食物，兔通常无犬齿。',evidence='兔和狼的牙齿')
add('microbe-distribution','7上','第二单元 第三章 微生物','检测环境中的细菌和真菌','学生实验','microbe',[opt('sample','取样条件',[('air','空气暴露'),('washed','规范洗手后'),('unwashed','未洗手'),('sealed','未接种对照')]),num('day','观察日序',0,5,2)],'理解接种、对照与菌落，并规范比较微生物分布。','经教师准备的密闭培养皿|无菌取样用品|记录表','保持培养条件一致，设置未接种对照。|只改变取样位置或洗手条件。|密闭观察形态，按统一标准记录。','不同样本可能出现不同菌落；对照可检查污染。|菌落是细胞繁殖形成的群体，不能凭颜色判断是否致病。','环境微生物分布广泛，检测需控制污染并保留对照。','培养前灭菌、冷却后接种|菌落与单个细胞不同','不能打开培养后的未知菌落嗅闻|不能将示意菌落数量当真实检测结果',('未接种对照也长出菌落说明什么？','可能存在灭菌不充分或操作污染，应检查操作，不能直接归因于待测样本。'),('洗手前后皿不同，未接种皿也出现大量菌落，能可靠比较吗？','对照应检验背景污染。','对照异常表示体系可能被污染。','需改善操作并重新比较。'),'证据不可靠，应查明污染并重做。',(10,),safety='仅教师监督的学校实验；培养后始终密封，由教师统一灭菌处置。')
add('bacteria','7上','第二单元 第三章 微生物','观察细菌的基本结构','小实验','anatomy',[opt('shape','形态',[('coccus','球状'),('rod','杆状'),('spiral','螺旋状')]),FOCUS[0]],'比较细菌与真核细胞，理解无成形细胞核。','细菌结构模型|显微照片资料','先辨认细胞壁、细胞膜与细胞质。|定位遗传物质集中的区域。|比较有无成形细胞核及其他结构。','细菌有DNA，但没有由核膜包围的成形细胞核。|并非所有细菌都具有鞭毛或荚膜。','细菌是单细胞原核生物，不能把“无成形细胞核”等同“无遗传物质”。','原核与真核区别|形态不是致病性判断标准','不能认为细菌都对人有害',('细菌没有成形细胞核，还能遗传吗？','能，其遗传物质可以复制并传给子代。'),('判断“细菌无成形细胞核，所以没有DNA”。','区分细胞核结构与遗传物质。','细菌有DNA，只是不位于成形细胞核中。','指出因果推断错误。'),'说法错误；细菌具有DNA，但没有成形细胞核。',evidence='细菌的基本结构')
add('fungi','7上','第二单元 第三章 微生物','观察酵母菌和霉菌','学生实验','microscope',MIC+[opt('specimen','材料',[('yeast','酵母菌'),('mold','霉菌永久装片')])],'比较单细胞真菌与菌丝构成的真菌。','酵母菌教学液或永久装片|霉菌永久装片|显微镜','规范制片并由低倍观察。|观察酵母细胞、芽体及染色后的细胞核。|用永久装片观察霉菌菌丝和孢子结构。','酵母菌常呈卵圆形，可见出芽。|霉菌由菌丝构成，可形成孢子。','真菌有成形细胞核，通常不能通过光合作用制造有机物。','酵母菌是真菌不是细菌|出芽与孢子繁殖','不能凭绿色就说霉菌有叶绿体',('酵母菌与细菌最重要的结构区别是什么？','酵母菌具有成形细胞核，细菌没有。'),('显微图见卵圆细胞旁有小芽体，能否据此说是细菌分裂？','结合细胞形态和出芽现象。','酵母菌可通过出芽产生后代。','还需细胞核等信息共同确认。'),'现象符合酵母菌出芽，不能直接判为细菌分裂。',(11,),safety='使用教师准备材料；不培养、打开或吸入未知霉菌孢子。')
add('fermentation','7上','第二单元 第三章 微生物','利用细菌或真菌制作发酵食品','拓展探究','microbe',[opt('product','发酵项目',[('bread','比较面包酵母发酵'),('yogurt','酸奶装置'),('pickle','泡菜条件')]),opt('temperature','温度条件',[('cold','偏低'),('suitable','适宜'),('hot','高温处理')]),opt('culture','接种',[('yes','合适的食品菌种'),('no','未接种对照')])],'比较不同发酵食品所利用的微生物及主要代谢特点。','食品级菌种|模型容器|条件记录表','明确食品种类与合适菌种。|保持原料等条件一致，设置对照。|记录膨胀、凝乳或酸度变化，并区分模型与实测。','酵母产生气体可使面团膨松；乳酸菌产酸可促使乳凝固。|低温通常减慢发酵，高温处理可影响菌种活性。','发酵依赖适合的微生物和条件，成品外观不能保证食用安全。','对照与重复|泡菜亚硝酸盐需检测而非凭颜色估计','不是所有发酵都产酒精|本模拟不能认证食品安全',('面团膨胀为什么不能证明只有无氧呼吸？','酵母在有氧和无氧条件下都能产生二氧化碳，需结合供氧等条件判断。'),('比较两种食品酵母发酵效果，应怎样控制条件？','只改变酵母菌种。','面粉量、加水量、温度和时间等保持一致。','比较相同时间的面团体积或收集气体体积，并设置重复。'),'以菌种为唯一变量，在相同条件下重复比较发酵指标。',(54,55,56),safety='页面仅作方案模拟；实物食品制作由教师或家长按卫生规范指导，实验培养物不得食用。')
add('classification','7上','第二单元 第四章 生物的分类','对植物和动物进行分类','小实验','anatomy',[opt('group','分类任务',[('plants','植物类群'),('animals','动物类群')]),opt('criterion','第一项判断',[('structure','形态与繁殖特征'),('habitat','只看生活环境')])],'选择稳定的多项特征建立分类路径。','生物特征卡|分类检索表','列出每个对象的关键特征。|选择互斥的判断条件逐级分类。|用新对象检查分类表能否得到一致结果。','只按栖息地容易将不同类群混在一起。|越低的分类单位通常共同特征越多。','科学分类以形态结构、生理和繁殖等特征为基础。','分类单位|检索表每步条件清楚','不能按有益或有害作为稳定自然分类',('鲸与鲫鱼都在水中，为何不归入同类？','鲸用肺呼吸、胎生哺乳，鲫鱼用鳃呼吸等，关键特征不同。'),('以“是否生活在水中”作为鱼类唯一标准是否可靠？','列举同环境不同类群的反例。','鲸等水生哺乳动物也生活在水中。','改用鳃、鳍等结合生殖的多项证据。'),'不可靠；应依据形态结构和生理特征综合判断。',evidence='对植物进行分类|对动物进行分类')
add('resources','7上','第二单元 第四章 生物的分类','调查生物资源并制作植物标牌','拓展探究','survey',[num('identified','已确认种数',0,80,18),num('unknown','待鉴定种数',0,30,4),num('plots','调查样区数',1,20,3)],'开展生物资源调查，保留鉴定证据并制作准确标牌。','相机与记录表|可靠图鉴|非伤树式标牌','确定调查边界和记录项目。|拍照观察，不采集受保护物种。|核对名称及特征，为标牌注明信息来源。','同物异名或重复记录会影响种数统计。|无法确认的对象应保留待定编号。','资源调查应可追溯，物种数量不能代替全部生物多样性指标。','调查对象与范围明确|不确定性如实记录','不能将个体数当种数|不能随意在树干钉钉挂牌',('尚未鉴定的对象应如何处理？','记录照片、地点与特征，保留待定编号，不强行编造名称。'),('确认18种、4个待定类型，能报告22个已确认物种吗？','区分已确认种与待定类型。','待定类型可能包含重复种。','分别报告18种及4个待鉴定类型。'),'不能；应分别报告已确认种与待定记录。',evidence='调查本地区的某种生物资源|给校园内的植物挂牌|调查当地食用菌的种类及生产情况',safety='野外调查结伴并遵守边界；不采食野生菌或未知植物。')
